def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    sorted_nums = sorted(set(nums))

    result: list[str] = []
    start = prev = sorted_nums[0]
    count = 1

    for n in sorted_nums[1:]:
        if n == prev + 1:
            count += 1
        else:
            if count >= 3:
                result.append(f"{start}..{prev}")
            else:
                result.append(str(start))
            start = prev = n
            count = 1

    if count >= 3:
        result.append(f"{start}..{prev}")
    else:
        result.append(str(start))

    return ",".join(result)
