import re

# Matches an amount after stripping the "$" and thousands separators, e.g.
# "1234.50", "1,234.50", "-5.00", "1000". Uses ASCII digits only.
_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(?:,[0-9]{3})*(?:\.[0-9]+)?")


def _parse_amount(amount) -> float | None:
    """Parse an amount string like "$1,234.50", "1234.5", "-$5.00" or "$1,000".

    Returns the numeric value as a float, or ``None`` when the amount cannot be
    parsed (empty, non-numeric, or containing other characters).
    """
    if not isinstance(amount, str):
        return None
    cleaned = amount.strip().replace("$", "").replace(",", "")
    if not cleaned or not _AMOUNT_RE.fullmatch(cleaned):
        return None
    try:
        return float(cleaned)
    except ValueError:
        return None


def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    """Return the top ``n`` customers by total amount.

    - Amounts are summed per customer (case-insensitive; the reported name is
      the trimmed spelling of that customer's first valid row).
    - Rows with an empty customer name or an unparseable amount are skipped.
    - Totals are rounded to 2 decimals.
    - Results are sorted by total descending, then by name ascending.
    """
    totals: dict[str, dict[str, float]] = {}

    for row in rows:
        if not isinstance(row, dict):
            continue
        name = row.get("customer")
        amount = row.get("amount")
        if not isinstance(name, str) or not isinstance(amount, str):
            continue

        trimmed = name.strip()
        if not trimmed:
            continue

        value = _parse_amount(amount)
        if value is None:
            continue

        key = trimmed.lower()
        if key not in totals:
            totals[key] = {"name": trimmed, "total": 0.0}
        totals[key]["total"] += value

    results = [(info["name"], round(info["total"], 2)) for info in totals.values()]
    results.sort(key=lambda item: (-item[1], item[0]))
    return results[:n]
